$metric=function(string $sql,array $params=[])use($pdo){$q=$pdo->prepare($sql);$q->execute($params);return $q->fetchColumn();};
$metrics=[
 ['Registered establishments',$metric('SELECT COUNT(*) FROM establishments'.($site?' WHERE id='.(int)$site:''))],
 ['Telemetry readings',$metric('SELECT COUNT(*) FROM sensor_readings sr JOIN device_assignments da ON da.id=sr.device_assignment_id JOIN grease_traps g ON g.id=da.grease_trap_id JOIN establishments e ON e.id=g.establishment_id WHERE sr.recorded_at>=? AND sr.recorded_at<?'.$siteCondition,[$start,$end])],
 ['Alerts triggered',$metric('SELECT COUNT(*) FROM alerts a JOIN device_assignments da ON da.id=a.device_assignment_id JOIN grease_traps g ON g.id=da.grease_trap_id JOIN establishments e ON e.id=g.establishment_id WHERE a.first_triggered_at>=? AND a.first_triggered_at<?'.$siteCondition,[$start,$end])],
 ['Oil surrenders',$metric('SELECT COUNT(*) FROM oil_surrenders os JOIN establishments e ON e.id=os.establishment_id WHERE os.surrendered_at>=? AND os.surrendered_at<?'.$siteCondition,[$start,$end])],
 ['Rewards distributed',$metric("SELECT COUNT(*) FROM incentive_transactions it JOIN establishments e ON e.id=it.establishment_id WHERE it.processed_at>=? AND it.processed_at<? AND it.status='DISTRIBUTED'".$siteCondition,[$start,$end])],
 ['Compliance events',$metric('SELECT COUNT(*) FROM compliance_ledger cl LEFT JOIN establishments e ON e.id=cl.establishment_id WHERE cl.event_timestamp>=? AND cl.event_timestamp<?'.($site?' AND cl.establishment_id='.(int)$site:''),[$start,$end])],
];
$options=phase7_report_options($pdo);$selectedName='All registered establishments';foreach($options['establishments'] as $o)if((int)$o['id']===$site)$selectedName=$o['business_name'];
$pageTitle='Formal Compliance Report';$activeNav='reports';require dirname(__DIR__).'/includes/header.php';
?>
